function validate([n, m, k]) {
  if (![n, m, k].every(Number.isInteger)) return 'n, m and k must be whole numbers.';
  if (n < 1 || n > 50) return 'n is between 1 and 50.';
  if (m < 1 || m > 100) return 'm is between 1 and 100.';
  if (k < 0 || k > n) return 'k is between 0 and n.';
  return null;
}

