function numOfArrays(n, m, k) {
  const MOD = 1e9 + 7;
  if (k === 0) return 0;
  let dp = Array.from({ length: m + 1 }, () => new Array(k + 1).fill(0));
  for (let j = 1; j <= m; j++) {
    dp[j][1] = 1;
  }
  for (let i = 2; i <= n; i++) {
    const next = Array.from({ length: m + 1 }, () => new Array(k + 1).fill(0));
    for (let c = 1; c <= k; c++) {
      let smaller = 0;
      for (let j = 1; j <= m; j++) {
        next[j][c] = (dp[j][c] * j + smaller) % MOD;
        smaller = (smaller + dp[j][c - 1]) % MOD;
      }
    }
    dp = next;
  }
  let total = 0;
  for (let j = 1; j <= m; j++) {
    total = (total + dp[j][k]) % MOD;
  }
  return total;
}

