function numOfArrays(n, m, k) {
  // Fill positions left to right, trying every value; memoize on (position, current maximum, cost so far).
  const MOD = 1e9 + 7;
  const memo = new Map();
  function count(pos, max, cost) {
    if (cost > k || cost + (n - pos) < k) return 0;
    if (pos === n) return 1;
    const key = (pos * 101 + max) * 52 + cost;
    if (memo.has(key)) return memo.get(key);
    let ways = 0;
    for (let value = 1; value <= m; value++) {
      const sub = value > max ? count(pos + 1, value, cost + 1) : count(pos + 1, max, cost);
      ways = (ways + sub) % MOD;
    }
    memo.set(key, ways);
    return ways;
  }
  return count(0, 0, 0);
}

