function generate(rand, size) {
  const n = size === 'large' ? 30 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 7);
  const m = size === 'large' ? 40 + Math.floor(rand() * 61) : 1 + Math.floor(rand() * 6);
  let k;
  if (rand() < 0.15) k = Math.floor(rand() * (n + 1));
  else k = 1 + Math.floor(rand() * Math.min(n, m));
  return [n, m, k];
